import type { Skill } from "../../types";
import type { SkillState } from "../../types/skill";
import { SkillBlockCanvas } from "./SkillBlockCanvas";
import { SkillBlockCard } from "./SkillBlockCard";

interface SkillBlockSectionProps {
  readonly skill: Skill;
  readonly blockId: string;
  /** Ids a `call:` step may target (block flow ids + skill ids), for call labels. */
  readonly callTargetIds: string[];
  readonly blockStatuses: SkillState["blocks"] | undefined;
  /** Flow id of the currently active block (highlights + default-expands it). */
  readonly activeFlowId: string | null;
  /** Focused step within the active block. */
  readonly activeStepId: string | null;
  /** Ordered step ids visited in this block, derived from conversation events. */
  readonly stepTrail: string[];
  readonly expanded: boolean;
  readonly onToggle: () => void;
}

/**
 * One ordered-block section of the skill document: the block card with its
 * runtime status and, while expanded, the inline flow canvas focused on the
 * active step. Renders nothing when the referenced block is missing from the
 * catalog (a stale section reference).
 */
export function SkillBlockSection({
  skill,
  blockId,
  callTargetIds,
  blockStatuses,
  activeFlowId,
  activeStepId,
  stepTrail,
  expanded,
  onToggle,
}: SkillBlockSectionProps) {
  const block = skill.blocks[blockId];
  if (!block) return null;

  const isActiveBlock = block.ordered_block_id === activeFlowId;
  return (
    <SkillBlockCard
      blockId={blockId}
      status={blockStatuses?.[block.ordered_block_id]?.status ?? "inactive"}
      expanded={expanded}
      onToggle={onToggle}
    >
      <SkillBlockCanvas
        blockId={blockId}
        block={block}
        callTargetIds={callTargetIds}
        activeStepId={isActiveBlock ? activeStepId : null}
        stepTrail={stepTrail}
      />
    </SkillBlockCard>
  );
}
